24	#define VG_PROVISION_DIR "/data/velaguard/provision"
25	
26	/* NuttX declares these in <sys/statfs.h>; the desktop libc used by the host
27	 * tests does not, and the values are the same on both.
28	 */
29	
30	#ifndef PROC_SUPER_MAGIC
31	#  define PROC_SUPER_MAGIC 0x9fa0
32	#endif
33	
34	#ifndef TMPFS_MAGIC
35	#  define TMPFS_MAGIC 0x01021994
36	#endif
37	
38	/* The credentials only survive a reboot if /data is the eMMC volume.  The
39	 * agent mounts tmpfs on /data when stat("/data") fails, so a boot order or
40	 * eMMC fault silently turns every later write into a RAM write.  Writing
41	 * credentials there looks successful, reports a healthy status, and is gone
42	 * after the next restart - exactly the state the board was found in on
43	 * 2026-09-17, where provision/ and config.json were both absent while the
44	 * sealed blob had been "written" days earlier.
45	 */
46	
47	int vg_provision_store_is_persistent(const char *path)
48	{
49	  struct statfs st;
50	
51	  if (path == NULL || path[0] == '\0')
52	    {
53	      return -EINVAL;
54	    }
55	
56	  if (statfs(path, &st) != 0)
57	    {
58	      return (errno != 0) ? -errno : -EIO;
59	    }
60	
61	  if (st.f_type == TMPFS_MAGIC || st.f_type == PROC_SUPER_MAGIC)
62	    {
63	      return -ENODEV;
64	    }
65	
66	  return 0;
67	}
