69	static int json_escape(const char *in, char *out, size_t outsz)
70	{
71	  size_t o = 0;
72	
73	  if (outsz == 0)
74	    {
75	      return -EINVAL;
76	    }
77	
78	  for (; *in != '\0'; in++)
79	    {
80	      char c = *in;
81	
82	      if (c == '"' || c == '\\')
83	        {
84	          if (o + 2 >= outsz)
85	            {
86	              return -ENOSPC;
87	            }
88	
89	          out[o++] = '\\';
90	        }
91	
92	      if (o + 1 >= outsz)
93	        {
94	          return -ENOSPC;
95	        }
96	
97	      out[o++] = c;
98	    }
99	
100	  out[o] = '\0';
101	  return 0;
102	}
103	
104	static int json_get_string(const char *json, const char *key,
105	                           char *out, size_t outsz)
106	{
107	  char pattern[48];
108	  const char *p;
109	  const char *start;
110	  size_t i;
111	
112	  snprintf(pattern, sizeof(pattern), "\"%s\"", key);
113	  p = strstr(json, pattern);
114	  if (p == NULL)
115	    {
116	      return -ENOENT;
117	    }
118	
119	  p = strchr(p, ':');
120	  if (p == NULL)
121	    {
122	      return -EINVAL;
123	    }
124	
125	  p++;
126	  while (*p == ' ' || *p == '\t')
127	    {
128	      p++;
129	    }
130	
131	  if (*p != '"')
132	    {
133	      return -EINVAL;
134	    }
135	
136	  start = p + 1;
137	  for (i = 0; start[i] != '\0'; i++)
138	    {
139	      if (start[i] == '"' && (i == 0 || start[i - 1] != '\\'))
140	        {
141	          if (i + 1 >= outsz)
142	            {
143	              return -ENOSPC;
144	            }
145	
146	          memcpy(out, start, i);
147	          out[i] = '\0';
148	          return 0;
149	        }
150	    }
151	
152	  return -EINVAL;
153	}
