160	int vg_provision_parse_endpoint(const char *endpoint,
161	                                char *host, size_t hostsz,
162	                                char *path, size_t pathsz,
163	                                char *port, size_t portsz)
164	{
165	  const char *p;
166	  const char *slash;
167	  const char *host_start;
168	  size_t host_len;
169	
170	  if (endpoint == NULL || host == NULL || path == NULL || port == NULL)
171	    {
172	      return -EINVAL;
173	    }
174	
175	  snprintf(port, portsz, "443");
176	
177	  p = endpoint;
178	  if (strncmp(p, "https://", 8) == 0)
179	    {
180	      p += 8;
181	    }
182	  else if (strncmp(p, "http://", 7) == 0)
183	    {
184	      p += 7;
185	      snprintf(port, portsz, "80");
186	    }
187	
188	  host_start = p;
189	  slash = strchr(p, '/');
190	  if (slash == NULL)
191	    {
192	      host_len = strlen(host_start);
193	      if (host_len + 1 > hostsz)
194	        {
195	          return -ENOSPC;
196	        }
197	
198	      memcpy(host, host_start, host_len);
199	      host[host_len] = '\0';
200	      snprintf(path, pathsz, "/v1/chat/completions");
201	      return 0;
202	    }
203	
204	  host_len = (size_t)(slash - host_start);
205	  if (host_len + 1 > hostsz)
206	    {
207	      return -ENOSPC;
208	    }
209	
210	  memcpy(host, host_start, host_len);
211	  host[host_len] = '\0';
212	
213	  if (strcmp(slash, "/v1") == 0 || strcmp(slash, "/v1/") == 0)
214	    {
215	      snprintf(path, pathsz, "/v1/chat/completions");
216	    }
217	  else
218	    {
219	      snprintf(path, pathsz, "%s", slash);
220	      if (strstr(path, "chat/completions") == NULL)
221	        {
222	          size_t n = strlen(path);
223	
224	          if (n + 1 < pathsz && path[n - 1] != '/')
225	            {
226	              strcat(path, "/");
227	              n++;
228	            }
229	
230	          if (n + 20 < pathsz)
231	            {
232	              strcat(path, "chat/completions");
233	            }
234	        }
235	    }
236	
237	  return 0;
238	}
