240	/* Append with an explicit bound, and use it instead of snprintf for the
241	 * credential JSON.  Two reasons: the formatter cannot be proven safe here (the
242	 * field types allow a worst case of about 860 bytes while the crypto layer
243	 * caps the plaintext at 512), and a silently truncated document still passes
244	 * for a credential blob to every later step.  Building it by hand makes the
245	 * overflow impossible and reports it at the point of the copy.
246	 */
247	
248	static int json_append(char *out, size_t outsz, size_t *pos,
249	                       const char *s, size_t n)
250	{
251	  if (*pos + n >= outsz)
252	    {
253	      return -ENOSPC;
254	    }
255	
256	  memcpy(out + *pos, s, n);
257	  *pos += n;
258	  out[*pos] = '\0';
259	  return 0;
260	}
