262	static int cred_to_json(const struct vg_llm_credentials *cred,
263	                        char *out, size_t outsz)
264	{
265	  char key_esc[VG_PROVISION_API_KEY_MAX * 2];
266	  char host_esc[VG_PROVISION_HOST_MAX * 2];
267	  char path_esc[VG_PROVISION_PATH_MAX * 2];
268	  size_t pos = 0;
269	  int ret;
270	
271	  ret = json_escape(cred->api_key, key_esc, sizeof(key_esc));
272	  if (ret < 0)
273	    {
274	      return ret;
275	    }
276	
277	  ret = json_escape(cred->host, host_esc, sizeof(host_esc));
278	  if (ret < 0)
279	    {
280	      return ret;
281	    }
282	
283	  ret = json_escape(cred->path, path_esc, sizeof(path_esc));
284	  if (ret < 0)
285	    {
286	      return ret;
287	    }
288	
289	  if (outsz > 0)
290	    {
291	      out[0] = '\0';
292	    }
293	
294	#define VG_JSON_PUT(lit)                                                     \
295	  do                                                                         \
296	    {                                                                        \
297	      ret = json_append(out, outsz, &pos, lit, sizeof(lit) - 1);             \
298	      if (ret < 0)                                                           \
299	        {                                                                    \
300	          return ret;                                                        \
301	        }                                                                    \
302	    }                                                                        \
303	  while (0)
304	
305	#define VG_JSON_PUT_STR(s)                                                   \
306	  do                                                                         \
307	    {                                                                        \
308	      ret = json_append(out, outsz, &pos, s, strlen(s));                     \
309	      if (ret < 0)                                                           \
310	        {                                                                    \
311	          return ret;                                                        \
312	        }                                                                    \
313	    }                                                                        \
314	  while (0)
315	
316	  VG_JSON_PUT("{");
317	  VG_JSON_PUT("\"host\":\"");
318	  VG_JSON_PUT_STR(host_esc);
319	  VG_JSON_PUT("\",\"path\":\"");
320	  VG_JSON_PUT_STR(path_esc);
321	  VG_JSON_PUT("\",\"port\":\"");
322	  VG_JSON_PUT_STR(cred->port);
323	  VG_JSON_PUT("\",\"model\":\"");
324	  VG_JSON_PUT_STR(cred->model);
325	  VG_JSON_PUT("\",\"api_key\":\"");
326	  VG_JSON_PUT_STR(key_esc);
327	  VG_JSON_PUT("\"}");
328	
329	#undef VG_JSON_PUT
330	#undef VG_JSON_PUT_STR
331	
332	  return 0;
333	}
334	
335	static int json_to_cred(const char *json, struct vg_llm_credentials *out)
336	{
337	  int ret;
338	
339	  memset(out, 0, sizeof(*out));
340	  ret = json_get_string(json, "host", out->host, sizeof(out->host));
341	  if (ret < 0)
342	    {
343	      return ret;
344	    }
345	
346	  ret = json_get_string(json, "path", out->path, sizeof(out->path));
347	  if (ret < 0)
348	    {
349	      return ret;
350	    }
351	
352	  ret = json_get_string(json, "port", out->port, sizeof(out->port));
353	  if (ret < 0)
354	    {
355	      return ret;
356	    }
357	
358	  ret = json_get_string(json, "model", out->model, sizeof(out->model));
359	  if (ret < 0)
360	    {
361	      return ret;
362	    }
363	
364	  return json_get_string(json, "api_key", out->api_key, sizeof(out->api_key));
365	}
