374	int vg_provision_seal(const struct vg_llm_credentials *cred)
375	{
376	  uint8_t uid[VG_PROVISION_UID_LEN];
377	  char plain[640];
378	  uint8_t blob[768];
379	  size_t blob_len;
380	  int ret;
381	
382	  if (cred == NULL || cred->api_key[0] == '\0' || cred->host[0] == '\0')
383	    {
384	      return -EINVAL;
385	    }
386	
387	  ret = mkdir(VG_PROVISION_DIR, 0700);
388	  if (ret < 0 && errno != EEXIST)
389	    {
390	      return -errno;
391	    }
392	
393	  ret = cred_to_json(cred, plain, sizeof(plain));
394	  if (ret < 0)
395	    {
396	      return ret;
397	    }
398	
399	  /* The crypto layer refuses anything past this bound.  Checking here keeps
400	   * the two limits in one place and reports a credential that is simply too
401	   * large, rather than a seal error the operator has to trace back. */
402	
403	  if (strlen(plain) > VG_PROVISION_PLAIN_MAX)
404	    {
405	      return -E2BIG;
406	    }
407	
408	  ret = vg_provision_read_uid(uid);
409	  if (ret < 0)
410	    {
411	      return ret;
412	    }
413	
414	  ret = vg_provision_crypto_seal(uid, (const uint8_t *)plain, strlen(plain),
415	                                 blob, sizeof(blob), &blob_len);
416	  if (ret < 0)
417	    {
418	      return ret;
419	    }
420	
421	  return vg_file_replace(VG_PROVISION_FILE, blob, blob_len, 0600);
422	}
423	
424	int vg_provision_load(struct vg_llm_credentials *out)
425	{
426	  static uint8_t uid[VG_PROVISION_UID_LEN];
427	  static uint8_t blob[768];
428	  static char plain[640];
429	  size_t plain_len;
430	  ssize_t n;
431	  int fd;
432	  int ret;
433	
434	  if (out == NULL)
435	    {
436	      return -EINVAL;
437	    }
438	
439	  fd = open(VG_PROVISION_FILE, O_RDONLY);
440	  if (fd < 0)
441	    {
442	      return -errno;
443	    }
444	
445	  n = read(fd, blob, sizeof(blob));
446	  close(fd);
447	  if (n <= 0)
448	    {
449	      return (n == 0) ? -EINVAL : -EIO;
450	    }
451	
452	  ret = vg_provision_read_uid(uid);
453	  if (ret < 0)
454	    {
455	      return ret;
456	    }
457	
458	  ret = vg_provision_crypto_open(uid, blob, (size_t)n,
459	                                 (uint8_t *)plain, sizeof(plain), &plain_len);
460	  if (ret < 0)
461	    {
462	      return ret;
463	    }
464	
465	  plain[plain_len] = '\0';
466	  return json_to_cred(plain, out);
467	}
