469	int vg_provision_apply_llm_config(void)
470	{
471	  struct vg_llm_credentials cred;
472	  char key_esc[VG_PROVISION_API_KEY_MAX * 2];
473	  static char backend[768];
474	  static char body[1536];
475	  int ret;
476	
477	  if (!vg_provision_is_present())
478	    {
479	      return -ENOENT;
480	    }
481	
482	  /* Refuse before decrypting anything: on a RAM-backed /data the file below
483	   * would be written and then discarded at the next reboot, leaving the board
484	   * with no backend and no trace of why. */
485	
486	  ret = vg_provision_store_is_persistent("/data/agent/config");
487	  if (ret == -ENOENT)
488	    {
489	      ret = vg_provision_store_is_persistent("/data");
490	    }
491	
492	  if (ret != 0)
493	    {
494	      return ret;
495	    }
496	
497	  ret = vg_provision_load(&cred);
498	  if (ret < 0)
499	    {
500	      return ret;
501	    }
502	
503	  ret = mkdir("/data/agent/config", 0700);
504	  if (ret < 0 && errno != EEXIST)
505	    {
506	      return -errno;
507	    }
508	
509	  ret = json_escape(cred.api_key, key_esc, sizeof(key_esc));
510	  if (ret < 0)
511	    {
512	      return ret;
513	    }
514	
515	  snprintf(backend, sizeof(backend),
516	           "{\\\"host\\\":\\\"%s\\\",\\\"path\\\":\\\"%s\\\","
517	           "\\\"port\\\":\\\"%s\\\",\\\"api_key\\\":\\\"%s\\\","
518	           "\\\"model\\\":\\\"%s\\\",\\\"priority\\\":0,\\\"cost_tier\\\":1}",
519	           cred.host, cred.path, cred.port, key_esc, cred.model);
520	
521	  snprintf(body, sizeof(body),
522	           "{"
523	           "\"llm_host\":\"%s\","
524	           "\"llm_path\":\"%s\","
525	           "\"llm_port\":\"%s\","
526	           "\"model\":\"%s\","
527	           "\"api_key\":\"%s\","
528	           "\"llm_backend_0\":\"%s\""
529	           "}",
530	           cred.host, cred.path, cred.port, cred.model, key_esc, backend);
531	
532	  return vg_file_replace("/data/agent/config/config.json", body,
533	                         strlen(body), 0600);
534	}
