547	/* Whether the agent has something to call out with.  This mirrors the router's
548	 * own condition: it reports "No available backend" exactly when no slot carries
549	 * a host, and the router is fed only from the config.json written below.  The
550	 * check reads that file rather than the sealed blob, because a sealed blob
551	 * whose apply step never ran is precisely the failure this is meant to catch.
552	 *
553	 * The parse is separate from the read so the host tests can cover it without a
554	 * board: the file lives at a fixed /data path the desktop cannot write.
555	 */
556	
557	bool vg_provision_creds_ready_in(const char *json)
558	{
559	  if (json == NULL || json[0] == '\0')
560	    {
561	      return false;
562	    }
563	
564	  /* The value must be non-empty, not merely present: a masked or blanked key
565	   * leaves the router with a host but makes every call fail instantly. */
566	
567	  if (strstr(json, "\"llm_host\":\"") == NULL ||
568	      strstr(json, "\"llm_host\":\"\"") != NULL)
569	    {
570	      return false;
571	    }
572	
573	  if (strstr(json, "\"api_key\":\"") == NULL ||
574	      strstr(json, "\"api_key\":\"\"") != NULL)
575	    {
576	      return false;
577	    }
578	
579	  return true;
580	}
581	
582	bool vg_llm_credentials_ready(void)
583	{
584	  static char buf[1024];
585	  ssize_t n;
586	  int fd;
587	
588	  fd = open("/data/agent/config/config.json", O_RDONLY);
589	  if (fd < 0)
590	    {
591	      return false;
592	    }
593	
594	  n = read(fd, buf, sizeof(buf) - 1);
595	  close(fd);
596	
597	  if (n <= 0)
598	    {
599	      return false;
600	    }
601	
602	  buf[n] = '\0';
603	  return vg_provision_creds_ready_in(buf);
604	}
