1	/****************************************************************************
2	 * NSH: vgprovision — seal / inspect encrypted LLM credentials on eMMC.
3	 ****************************************************************************/
4	
5	#include <errno.h>
6	#include <fcntl.h>
7	#include <stdio.h>
8	#include <stdlib.h>
9	#include <string.h>
10	#include <pthread.h>
11	#include <sys/stat.h>
12	#include <unistd.h>
13	
14	#include <nuttx/config.h>
15	
16	#include "vg_provision.h"
17	
18	static void usage(void)
19	{
20	  printf("Usage:\n");
21	  printf("  vgprovision uid\n");
22	  printf("  vgprovision status\n");
23	  printf("  vgprovision wipe\n");
24	  printf("  vgprovision put <hex>\n");
25	  printf("  vgprovision commit\n");
26	  printf("  vgprovision apply\n");
27	}
28	
29	#define VG_STAGING_FILE "/data/velaguard/provision/.staging"
30	#define VG_PROVISION_DIR  "/data/velaguard/provision"
31	#define VG_APPLY_FLAG     "/data/velaguard/provision/.apply_on_boot"
32	
33	static int hex_nibble(char c)
34	{
35	  if (c >= '0' && c <= '9')
36	    {
37	      return c - '0';
38	    }
39	
40	  if (c >= 'a' && c <= 'f')
41	    {
42	      return c - 'a' + 10;
43	    }
44	
45	  if (c >= 'A' && c <= 'F')
46	    {
47	      return c - 'A' + 10;
48	    }
49	
50	  return -1;
51	}
52	
53	static int cmd_put(const char *hex)
54	{
55	  uint8_t buf[32];
56	  size_t n = 0;
57	  size_t len;
58	  int fd;
59	  ssize_t w;
60	
61	  if (hex == NULL)
62	    {
63	      return -EINVAL;
64	    }
65	
66	  len = strlen(hex);
67	  if (len == 0 || (len % 2) != 0 || len > sizeof(buf) * 2)
68	    {
69	      return -EINVAL;
70	    }
71	
72	  for (size_t i = 0; i < len; i += 2)
73	    {
74	      int hi = hex_nibble(hex[i]);
75	      int lo = hex_nibble(hex[i + 1]);
76	
77	      if (hi < 0 || lo < 0)
78	        {
79	          return -EINVAL;
80	        }
81	
82	      buf[n++] = (uint8_t)((hi << 4) | lo);
83	    }
84	
85	  (void)mkdir(VG_PROVISION_DIR, 0700);
86	  fd = open(VG_STAGING_FILE, O_WRONLY | O_CREAT | O_APPEND, 0600);
87	  if (fd < 0)
88	    {
89	      return -errno;
90	    }
91	
92	  w = write(fd, buf, n);
93	  close(fd);
94	  return (w == (ssize_t)n) ? 0 : -EIO;
95	}
96	
97	static int cmd_commit(void)
98	{
99	  struct stat st;
100	  int fd;
101	  int ret;
102	
103	  if (stat(VG_STAGING_FILE, &st) != 0 || st.st_size <= 0)
104	    {
105	      return -EINVAL;
106	    }
107	
108	  ret = rename(VG_STAGING_FILE, VG_PROVISION_FILE);
109	  if (ret < 0)
110	    {
111	      return -errno;
112	    }
113	
114	  printf("vgprovision: committed %s (%ld bytes)\n",
115	         VG_PROVISION_FILE, (long)st.st_size);
116	
117	  /* Say plainly whether the blob will still be there after a restart.  A
118	   * commit onto RAM-backed /data prints no other symptom at the time and only
119	   * shows up later as an agent with no backend. */
120	
121	  ret = vg_provision_store_is_persistent(VG_PROVISION_DIR);
122	  if (ret == -ENOENT)
123	    {
124	      ret = vg_provision_store_is_persistent("/data");
125	    }
126	
127	  if (ret != 0)
128	    {
129	      printf("vgprovision: WARNING store is not persistent (%d): "
130	             "credentials will be lost on reboot\n", ret);
131	    }
132	
133	  fd = open(VG_APPLY_FLAG, O_WRONLY | O_CREAT | O_TRUNC, 0600);
134	  if (fd >= 0)
135	    {
136	      close(fd);
137	    }
138	
139	  printf("vgprovision: reboot required to apply LLM config "
140	         "(this build has no reboot command; reset the board)\n");
141	  return 0;
142	}
