144	static void *apply_worker(FAR void *arg)
145	{
146	  int ret;
147	
148	  (void)arg;
149	  ret = vg_provision_apply_llm_config();
150	  printf("vgprovision: apply %d\n", ret);
151	  return NULL;
152	}
