154	static int cmd_apply_async(void)
155	{
156	  pthread_t tid;
157	  pthread_attr_t attr;
158	  int ret;
159	
160	  pthread_attr_init(&attr);
161	  pthread_attr_setstacksize(&attr, 8192);
162	  ret = pthread_create(&tid, &attr, apply_worker, NULL);
163	  pthread_attr_destroy(&attr);
164	  if (ret != 0)
165	    {
166	      return -ret;
167	    }
168	
169	  pthread_detach(tid);
170	  return 0;
171	}
