194	int main(int argc, char *argv[])
195	{
196	  int ret;
197	
198	  if (argc < 2)
199	    {
200	      usage();
201	      return 1;
202	    }
203	
204	  if (strcmp(argv[1], "uid") == 0)
205	    {
206	      print_uid();
207	      return 0;
208	    }
209	
210	  if (strcmp(argv[1], "status") == 0)
211	    {
212	      if (!vg_provision_is_present())
213	        {
214	          printf("vgprovision: not provisioned\n");
215	          return 1;
216	        }
217	
218	      printf("vgprovision: OK file=%s\n", VG_PROVISION_FILE);
219	      return 0;
220	    }
221	
222	  if (strcmp(argv[1], "wipe") == 0)
223	    {
224	      unlink(VG_STAGING_FILE);
225	      unlink(VG_PROVISION_FILE);
226	      printf("vgprovision: wiped\n");
227	      return 0;
228	    }
229	
230	  if (strcmp(argv[1], "put") == 0)
231	    {
232	      if (argc < 3)
233	        {
234	          usage();
235	          return 1;
236	        }
237	
238	      ret = cmd_put(argv[2]);
239	      if (ret < 0)
240	        {
241	          printf("vgprovision: put failed %d\n", ret);
242	          return 1;
243	        }
244	
245	      return 0;
246	    }
247	
248	  if (strcmp(argv[1], "commit") == 0)
249	    {
250	      ret = cmd_commit();
251	      return (ret < 0) ? 1 : 0;
252	    }
253	
254	  if (strcmp(argv[1], "apply") == 0)
255	    {
256	      ret = cmd_apply_async();
257	      if (ret < 0)
258	        {
259	          printf("vgprovision: apply start failed %d\n", ret);
260	          return 1;
261	        }
262	
263	      sleep(2);
264	      return 0;
265	    }
266	
267	  usage();
268	  return 1;
269	}
