1	/****************************************************************************
2	 * Device-bound SHA256 stream + HMAC-SHA256 for provision blobs (v1).
3	 ****************************************************************************/
4	
5	#include "vg_provision.h"
6	
7	#include <errno.h>
8	#include <string.h>
9	
10	#ifdef __NuttX__
11	#  include <mbedtls/sha256.h>
12	#endif
13	
14	#define VGPR_MAGIC0 'V'
15	#define VGPR_MAGIC1 'G'
16	#define VGPR_MAGIC2 'P'
17	#define VGPR_MAGIC3 'R'
18	#define VGPR_VERSION 1
19	
20	#define VGPR_HDR_SIZE 28
21	#define VGPR_TAG_SIZE 32
22	#define VGPR_NONCE_SIZE 16
23	
24	static void derive_keys(const uint8_t uid[VG_PROVISION_UID_LEN],
25	                        uint8_t aes_key[32], uint8_t mac_key[32])
26	{
27	#ifdef __NuttX__
28	  mbedtls_sha256_context sha;
29	  uint8_t master[32];
30	  static const char info[] = "velaguard:provision:v1:";
31	  static const char mac_info[] = "mac";
32	
33	  mbedtls_sha256_init(&sha);
34	  mbedtls_sha256_starts(&sha, 0);
35	  mbedtls_sha256_update(&sha, (const uint8_t *)info, sizeof(info) - 1);
36	  mbedtls_sha256_update(&sha, uid, VG_PROVISION_UID_LEN);
37	  mbedtls_sha256_finish(&sha, master);
38	  mbedtls_sha256_free(&sha);
39	
40	  memcpy(aes_key, master, 32);
41	
42	  mbedtls_sha256_init(&sha);
43	  mbedtls_sha256_starts(&sha, 0);
44	  mbedtls_sha256_update(&sha, master, sizeof(master));
45	  mbedtls_sha256_update(&sha, (const uint8_t *)mac_info, sizeof(mac_info) - 1);
46	  mbedtls_sha256_finish(&sha, mac_key);
47	  mbedtls_sha256_free(&sha);
48	#else
49	  (void)uid;
50	  memset(aes_key, 0x5a, 32);
51	  memset(mac_key, 0xa5, 32);
52	#endif
53	}
54	
55	#ifndef __NuttX__
56	
57	int vg_provision_crypto_seal(const uint8_t uid[VG_PROVISION_UID_LEN],
58	                             const uint8_t *plain, size_t plain_len,
59	                             uint8_t *out, size_t outsz, size_t *out_len)
60	{
61	  (void)uid;
62	  (void)plain;
63	  (void)plain_len;
64	  (void)out;
65	  (void)outsz;
66	  (void)out_len;
67	  return -ENOSYS;
68	}
69	
70	int vg_provision_crypto_open(const uint8_t uid[VG_PROVISION_UID_LEN],
71	                             const uint8_t *blob, size_t blob_len,
72	                             uint8_t *plain, size_t plainsz, size_t *plain_len)
73	{
74	  (void)uid;
75	  (void)blob;
76	  (void)blob_len;
77	  (void)plain;
78	  (void)plainsz;
79	  (void)plain_len;
80	  return -ENOSYS;
81	}
82	
83	#else
84	
85	static int hmac_sha256(const uint8_t key[32], const uint8_t *msg, size_t msg_len,
86	                       uint8_t tag[32])
87	{
88	  mbedtls_sha256_context sha;
89	  uint8_t ipad[64];
90	  uint8_t opad[64];
91	  uint8_t inner[32];
92	  size_t i;
93	
94	  memset(ipad, 0x36, sizeof(ipad));
95	  memset(opad, 0x5c, sizeof(opad));
96	  for (i = 0; i < 32; i++)
97	    {
98	      ipad[i] ^= key[i];
99	      opad[i] ^= key[i];
100	    }
101	
102	  mbedtls_sha256_init(&sha);
103	  mbedtls_sha256_starts(&sha, 0);
104	  mbedtls_sha256_update(&sha, ipad, sizeof(ipad));
105	  mbedtls_sha256_update(&sha, msg, msg_len);
106	  mbedtls_sha256_finish(&sha, inner);
107	  mbedtls_sha256_free(&sha);
108	
109	  mbedtls_sha256_init(&sha);
110	  mbedtls_sha256_starts(&sha, 0);
111	  mbedtls_sha256_update(&sha, opad, sizeof(opad));
112	  mbedtls_sha256_update(&sha, inner, sizeof(inner));
113	  mbedtls_sha256_finish(&sha, tag);
114	  mbedtls_sha256_free(&sha);
115	  return 0;
116	}
117	
118	static void stream_xor(const uint8_t stream_key[32], const uint8_t nonce[16],
119	                       const uint8_t *in, uint8_t *out, size_t len)
120	{
121	  mbedtls_sha256_context sha;
122	  uint8_t block[32];
123	  uint32_t idx = 0;
124	  size_t off = 0;
125	
126	  while (off < len)
127	    {
128	      uint8_t ctr[4];
129	
130	      mbedtls_sha256_init(&sha);
131	      mbedtls_sha256_starts(&sha, 0);
132	      mbedtls_sha256_update(&sha, stream_key, 32);
133	      mbedtls_sha256_update(&sha, nonce, 16);
134	      ctr[0] = (uint8_t)(idx);
135	      ctr[1] = (uint8_t)(idx >> 8);
136	      ctr[2] = (uint8_t)(idx >> 16);
137	      ctr[3] = (uint8_t)(idx >> 24);
138	      mbedtls_sha256_update(&sha, ctr, sizeof(ctr));
139	      mbedtls_sha256_finish(&sha, block);
140	      mbedtls_sha256_free(&sha);
141	
142	      for (size_t i = 0; i < 32 && off < len; i++, off++)
143	        {
144	          out[off] = in[off] ^ block[i];
145	        }
146	
147	      idx++;
148	    }
149	}
150	
151	int vg_provision_crypto_seal(const uint8_t uid[VG_PROVISION_UID_LEN],
152	                             const uint8_t *plain, size_t plain_len,
153	                             uint8_t *out, size_t outsz, size_t *out_len)
154	{
155	  uint8_t stream_key[32];
156	  uint8_t mac_key[32];
157	  uint8_t nonce[VGPR_NONCE_SIZE];
158	  size_t need;
159	  uint8_t tag[VGPR_TAG_SIZE];
160	
161	  if (plain_len > 512 || plain == NULL || out == NULL || out_len == NULL)
162	    {
163	      return -EINVAL;
164	    }
165	
166	  need = VGPR_HDR_SIZE + plain_len + VGPR_TAG_SIZE;
167	  if (outsz < need)
168	    {
169	      return -ENOSPC;
170	    }
171	
172	  derive_keys(uid, stream_key, mac_key);
173	
174	  for (size_t i = 0; i < sizeof(nonce); i++)
175	    {
176	      nonce[i] = (uint8_t)(plain_len ^ i ^ uid[i % VG_PROVISION_UID_LEN]);
177	    }
178	
179	  out[0] = VGPR_MAGIC0;
180	  out[1] = VGPR_MAGIC1;
181	  out[2] = VGPR_MAGIC2;
182	  out[3] = VGPR_MAGIC3;
183	  out[4] = VGPR_VERSION;
184	  out[5] = out[6] = out[7] = 0;
185	  memcpy(out + 8, nonce, VGPR_NONCE_SIZE);
186	  out[24] = (uint8_t)(plain_len & 0xff);
187	  out[25] = (uint8_t)((plain_len >> 8) & 0xff);
188	  out[26] = out[27] = 0;
189	
190	  stream_xor(stream_key, nonce, plain, out + VGPR_HDR_SIZE, plain_len);
191	  hmac_sha256(mac_key, out, VGPR_HDR_SIZE + plain_len, tag);
192	  memcpy(out + VGPR_HDR_SIZE + plain_len, tag, VGPR_TAG_SIZE);
193	  *out_len = need;
194	  return 0;
195	}
196	
197	int vg_provision_crypto_open(const uint8_t uid[VG_PROVISION_UID_LEN],
198	                             const uint8_t *blob, size_t blob_len,
199	                             uint8_t *plain, size_t plainsz, size_t *plain_len)
200	{
201	  uint8_t stream_key[32];
202	  uint8_t mac_key[32];
203	  uint8_t tag[VGPR_TAG_SIZE];
204	  uint8_t expect[VGPR_TAG_SIZE];
205	  uint32_t ct_len;
206	
207	  if (blob_len < VGPR_HDR_SIZE + VGPR_TAG_SIZE || blob == NULL ||
208	      plain == NULL || plain_len == NULL)
209	    {
210	      return -EINVAL;
211	    }
212	
213	  if (blob[0] != VGPR_MAGIC0 || blob[1] != VGPR_MAGIC1 ||
214	      blob[2] != VGPR_MAGIC2 || blob[3] != VGPR_MAGIC3 ||
215	      blob[4] != VGPR_VERSION)
216	    {
217	      return -EINVAL;
218	    }
219	
220	  ct_len = (uint32_t)blob[24] | ((uint32_t)blob[25] << 8);
221	  if (ct_len == 0 || ct_len > 512 ||
222	      blob_len != VGPR_HDR_SIZE + ct_len + VGPR_TAG_SIZE)
223	    {
224	      return -EINVAL;
225	    }
226	
227	  if (plainsz < ct_len)
228	    {
229	      return -ENOSPC;
230	    }
231	
232	  derive_keys(uid, stream_key, mac_key);
233	  memcpy(tag, blob + VGPR_HDR_SIZE + ct_len, VGPR_TAG_SIZE);
234	  hmac_sha256(mac_key, blob, VGPR_HDR_SIZE + ct_len, expect);
235	  if (memcmp(tag, expect, VGPR_TAG_SIZE) != 0)
236	    {
237	      return -EACCES;
238	    }
239	
240	  stream_xor(stream_key, blob + 8, blob + VGPR_HDR_SIZE, plain, ct_len);
241	  *plain_len = ct_len;
242	  return 0;
243	}
244	
245	#endif /* __NuttX__ */
