183	static int flush_publish_queue(void)
184	{
185	  int i;
186	
187	  /* QoS1 stays AWAITING_ACK until PUBACK; do not wait for mq_find NULL. */
188	  for (i = 0; i < 8 && g_client.error == MQTT_OK; i++)
189	    {
190	      mqtt_sync(&g_client);
191	      usleep(20000);
192	    }
193	
194	  if (g_client.error != MQTT_OK)
195	    {
196	      printf("vgnet: mqtt flush %s\n", mqtt_error_str(g_client.error));
197	      return -1;
198	    }
199	
200	  return 0;
201	}
