235	  n = fread(g_pt_buf, 1, sizeof(g_pt_buf) - 1, fp);
236	  int bad = ferror(fp) || n == sizeof(g_pt_buf) - 1;
237	  if (fclose(fp) != 0) bad = 1;
238	  if (bad) { printf("vgnet: point table unreadable or too large\n"); return -1; }
239	  g_pt_buf[n] = '\0';
