248	static void publish_point_table(void)
249	{
250	  int n;
251	
252	  /* A previous version's success must not suppress periodic retries for
253	   * an updated table whose read or publish fails. Only the network thread
254	   * owns this flag; notifications keep their separate dirty bit. */
255	  g_pt_sent = 0;
256	  n = load_point_table();
257	  if (n <= 0)
258	    {
259	      return;
260	    }
261	
262	  if (publish_raw("point_table", g_pt_buf, (size_t)n,
263	                  MQTT_PUBLISH_QOS_1 | MQTT_PUBLISH_RETAIN) == 0) g_pt_sent = 1;
264	}
265	
266	static void build_telemetry(void)
267	{
268	  static struct vg_live_snapshot snap;
269	  struct vg_mqtt_tel_pt pts[VG_DISCOVER_MAX_POINTS];
270	  struct vg_mqtt_tel_hist sent[VG_MQTT_TEL_HIST_MAX];
271	  uint32_t now;
272	  int i;
273	  int n;
274	  int nout;
275	  int sent_n;
276	
277	  memset(&snap, 0, sizeof(snap));
278	  if (vg_live_snapshot_read(CONFIG_VG_LIVE_VALUES_PATH, &snap) != 0 ||
279	      snap.n <= 0)
280	    {
281	      return;
282	    }
283	
284	  n = snap.n;
285	  if (n > VG_DISCOVER_MAX_POINTS)
286	    {
287	      n = VG_DISCOVER_MAX_POINTS;
288	    }
289	
290	  now = vg_live_now_ms();
291	  nout = 0;
292	  sent_n = 0;
293	  memset(sent, 0, sizeof(sent));
294	  for (i = 0; i < n; i++)
295	    {
296	      const char *id = snap.samples[i].id;
297	      int idx;
298	      int prev_known;
299	      int prev_ok;
300	
301	      idx = vg_mqtt_tel_hist_find(g_tel_hist, g_tel_hist_n, id);
302	      prev_known = (idx >= 0);
303	      prev_ok = prev_known ? (int)g_tel_hist[idx].last_ok : 0;
304	      if (!vg_mqtt_tel_want_send(snap.samples[i].ok, prev_known, prev_ok))
305	        {
306	          continue;
307	        }
308	
309	      pts[nout].id = snap.samples[i].id;
310	      pts[nout].value = snap.samples[i].value;
311	      pts[nout].ok = snap.samples[i].ok;
312	      pts[nout].age_ms = vg_live_age_ms(snap.tick_ms, now);
313	      nout++;
314	      (void)vg_mqtt_tel_hist_upsert(sent, &sent_n, VG_MQTT_TEL_HIST_MAX,
315	                                    id, snap.samples[i].ok);
316	    }
317	
318	  if (nout <= 0)
319	    {
320	      return;
321	    }
322	
323	  if (vg_mqtt_format_telemetry(g_tel_buf, sizeof(g_tel_buf), pts, nout) != 0)
324	    {
325	      return;
326	    }
327	
328	  pthread_mutex_lock(&g_qlock);
329	  memcpy(g_tel_sent, sent, sizeof(g_tel_sent));
330	  g_tel_sent_n = sent_n;
331	  g_tel_pending = 1;
332	  pthread_mutex_unlock(&g_qlock);
333	}
334	
335	static void drain_queues(void)
336	{
337	  char alarm_copy[VG_MQTT_ALARM_B];
338	  int send_pt;
339	  int send_tel;
340	
341	  for (; ; )
342	    {
343	      alarm_copy[0] = '\0';
344	      pthread_mutex_lock(&g_qlock);
345	      if (g_alarm_count > 0)
346	        {
347	          snprintf(alarm_copy, sizeof(alarm_copy), "%s",
348	                   g_alarm_q[g_alarm_head].json);
349	        }
350	
351	      pthread_mutex_unlock(&g_qlock);
352	      if (alarm_copy[0] == '\0')
353	        {
354	          break;
355	        }
356	
357	      if (publish_raw("alarm", alarm_copy, strlen(alarm_copy),
358	                      MQTT_PUBLISH_QOS_1) != 0)
359	        {
360	          return;
361	        }
362	
363	      pthread_mutex_lock(&g_qlock);
364	      if (g_alarm_count > 0 &&
365	          strcmp(g_alarm_q[g_alarm_head].json, alarm_copy) == 0)
366	        {
367	          g_alarm_q[g_alarm_head].used = 0;
368	          g_alarm_head = (g_alarm_head + 1) % VG_MQTT_ALARM_N;
369	          g_alarm_count--;
370	        }
371	
372	      pthread_mutex_unlock(&g_qlock);
373	    }
374	
375	  pthread_mutex_lock(&g_qlock);
376	  send_pt = g_pt_dirty;
377	  g_pt_dirty = 0;
378	  send_tel = g_tel_pending;
379	  pthread_mutex_unlock(&g_qlock);
380	
381	  if (send_pt)
382	    {
383	      publish_point_table();
384	    }
385	
386	  if (send_tel)
387	    {
388	      if (publish_raw("telemetry", g_tel_buf, strlen(g_tel_buf),
389	                      MQTT_PUBLISH_QOS_0) == 0)
390	        {
391	          int i;
392	
393	          pthread_mutex_lock(&g_qlock);
394	          for (i = 0; i < g_tel_sent_n; i++)
395	            {
396	              (void)vg_mqtt_tel_hist_upsert(g_tel_hist, &g_tel_hist_n,
397	                                            VG_MQTT_TEL_HIST_MAX,
398	                                            g_tel_sent[i].id,
399	                                            (int)g_tel_sent[i].last_ok);
400	            }
401	
402	          g_tel_pending = 0;
403	          pthread_mutex_unlock(&g_qlock);
404	        }
405	    }
406	}
