408	void vg_mqtt_enqueue_alarm(const char *id, const char *kind,
409	                           const char *state, float value, float thr,
410	                           const char *level, long long ts_ms)
411	{
412	  char alarm_id[80];
413	  char json[VG_MQTT_ALARM_B];
414	  struct vg_mqtt_alarm_slot *s;
415	  int slot;
416	
417	  if (id == NULL || id[0] == '\0' || kind == NULL || state == NULL)
418	    {
419	      return;
420	    }
421	
422	  pthread_mutex_lock(&g_qlock);
423	  ensure_boot_id();
424	  g_alarm_seq++;
425	  snprintf(alarm_id, sizeof(alarm_id), "%s-%08x-%u", vg_device_id(),
426	           (unsigned)g_boot_id, g_alarm_seq);
427	  pthread_mutex_unlock(&g_qlock);
428	  if (ts_ms == 0)
429	    {
430	      ts_ms = wall_ms();
431	    }
432	
433	  if (vg_mqtt_format_alarm(json, sizeof(json), vg_device_id(), alarm_id, id,
434	                           kind, state, value, thr, level, ts_ms) != 0)
435	    {
436	      return;
437	    }
438	
439	  pthread_mutex_lock(&g_qlock);
440	  if (g_alarm_count >= VG_MQTT_ALARM_N)
441	    {
442	      g_alarm_q[g_alarm_head].used = 0;
443	      g_alarm_head = (g_alarm_head + 1) % VG_MQTT_ALARM_N;
444	      g_alarm_count--;
445	    }
446	
447	  slot = (g_alarm_head + g_alarm_count) % VG_MQTT_ALARM_N;
448	  s = &g_alarm_q[slot];
449	  snprintf(s->json, sizeof(s->json), "%s", json);
450	  s->used = 1;
451	  g_alarm_count++;
452	  pthread_mutex_unlock(&g_qlock);
453	}
