462	void vg_mqtt_session_close(void)
463	{
464	  if (g_fd >= 0)
465	    {
466	      vg_tcp_close(&g_fd);
467	    }
468	
469	  memset(&g_client, 0, sizeof(g_client));
470	  g_fd = -1;
471	  g_online = false;
472	  g_pt_sent = 0;
473	}
474	
475	int vg_mqtt_session_open(vg_tcp_backend_t backend, const char *net_name)
476	{
477	  char port[8];
478	  uint8_t connflags;
479	  const char *id;
480	  int ret;
481	  int i;
482	
483	  vg_mqtt_session_close();
484	  strlcpy(g_net, net_name ? net_name : "none", sizeof(g_net));
485	  port_str(port, sizeof(port));
486	  id = vg_device_id();
487	  ensure_boot_id();
488	
489	  if (vg_mqtt_format_lwt(g_will, sizeof(g_will), id) != 0)
490	    {
491	      return -1;
492	    }
493	
494	  g_fd = vg_tcp_open(backend, CONFIG_VG_MQTT_BROKER_HOST, port);
495	  if (g_fd < 0)
496	    {
497	      printf("vgnet: tcp connect %s:%s via %s failed\n",
498	             CONFIG_VG_MQTT_BROKER_HOST, port,
499	             vg_tcp_backend_str(backend));
500	      return -1;
501	    }
502	
503	  mqtt_init(&g_client, g_fd, g_tx, sizeof(g_tx), g_rx, sizeof(g_rx),
504	            mqtt_ignore_inbound);
505	  connflags = MQTT_CONNECT_CLEAN_SESSION |
506	              MQTT_CONNECT_WILL_QOS_0 |
507	              MQTT_CONNECT_WILL_RETAIN;
508	  if (vg_mqtt_topic(g_topic, sizeof(g_topic), id, "status") != 0)
509	    {
510	      vg_mqtt_session_close();
511	      return -1;
512	    }
513	
514	  ret = mqtt_connect(&g_client, id, g_topic, g_will, strlen(g_will),
515	                     mqtt_user(), mqtt_pass(), connflags,
516	                     (uint16_t)CONFIG_VG_MQTT_KEEPALIVE);
517	  if (ret != MQTT_OK)
518	    {
519	      vg_mqtt_session_close();
520	      return -1;
521	    }
522	
523	  for (i = 0; i < 80 && !g_client.event_connect &&
524	       g_client.error == MQTT_OK; i++)
525	    {
526	      mqtt_sync(&g_client);
527	      usleep(50000);
528	    }
529	
530	  if (!g_client.event_connect)
531	    {
532	      printf("vgnet: no CONNACK via %s\n", vg_tcp_backend_str(backend));
533	      vg_mqtt_session_close();
534	      return -1;
535	    }
536	
537	  g_online = true;
538	  publish_status();
539	  pthread_mutex_lock(&g_qlock);
540	  g_pt_dirty = 1;
541	  g_next_period_ms = now_ms() + VG_MQTT_PERIOD_MS;
542	  pthread_mutex_unlock(&g_qlock);
543	  drain_queues();
544	  if (flush_publish_queue() != 0)
545	    {
546	      vg_mqtt_session_close();
547	      return -1;
548	    }
549	
550	  printf("vgnet: mqtt online network=%s backend=%s device=%s\n",
551	         g_net, vg_tcp_backend_str(backend), id);
552	  return 0;
553	}
554	
555	void vg_mqtt_session_poll(void)
556	{
557	  uint64_t t;
558	
559	  if (g_fd < 0 || !g_online)
560	    {
561	      return;
562	    }
563	
564	  mqtt_sync(&g_client);
565	  if (g_client.error != MQTT_OK)
566	    {
567	      printf("vgnet: mqtt error %s\n", mqtt_error_str(g_client.error));
568	      vg_mqtt_session_close();
569	      return;
570	    }
571	
572	  t = now_ms();
573	  pthread_mutex_lock(&g_qlock);
574	  if (t >= g_next_period_ms)
575	    {
576	      g_next_period_ms = t + VG_MQTT_PERIOD_MS;
577	      pthread_mutex_unlock(&g_qlock);
578	      publish_status();
579	      build_telemetry();
580	      pthread_mutex_lock(&g_qlock);
581	      if (!g_pt_sent)
582	        {
583	          g_pt_dirty = 1;
584	        }
585	
586	      pthread_mutex_unlock(&g_qlock);
587	    }
588	  else
589	    {
590	      pthread_mutex_unlock(&g_qlock);
591	    }
592	
593	  drain_queues();
594	  mqtt_sync(&g_client);
595	}
