91	
92	static int parse_args(int argc, FAR char *argv[],
93	                      FAR struct vgmqtt_cfg_s *cfg)
94	{
95	  int opt;
96	
97	  memset(cfg, 0, sizeof(*cfg));
98	#ifdef CONFIG_VG_MQTT_BROKER_HOST
99	  cfg->host   = CONFIG_VG_MQTT_BROKER_HOST;
100	#else
101	  cfg->host   = NULL;
102	#endif
103	#ifdef CONFIG_VG_MQTT_USERNAME
104	  if (CONFIG_VG_MQTT_USERNAME[0] != '\0')
105	    {
106	      cfg->user = CONFIG_VG_MQTT_USERNAME;
107	    }
108	#endif
109	#ifdef CONFIG_VG_MQTT_PASSWORD
110	  if (CONFIG_VG_MQTT_PASSWORD[0] != '\0')
111	    {
112	      cfg->pass = CONFIG_VG_MQTT_PASSWORD;
113	    }
114	#endif
115	  cfg->port   = VGMQTT_DEFAULT_PORT;
116	  cfg->qos    = 0;
117	  cfg->retain = true;
118	  cfg->wait_secs = 0;
119	
120	  while ((opt = getopt(argc, argv, "h:p:u:P:t:m:q:r:w:")) != ERROR)
121	    {
122	      switch (opt)
123	        {
124	          case 'h':
125	            cfg->host = optarg;
126	            break;
127	
128	          case 'p':
129	            cfg->port = optarg;
130	            break;
131	
132	          case 'u':
133	            cfg->user = optarg;
134	            break;
135	
136	          case 'P':
137	            cfg->pass = optarg;
138	            break;
139	
140	          case 't':
141	            cfg->topic = optarg;
142	            break;
143	
144	          case 'm':
145	            cfg->msg = optarg;
146	            break;
147	
148	          case 'q':
149	            cfg->qos = (uint8_t)strtol(optarg, NULL, 10);
150	            break;
151	
152	          case 'r':
153	            cfg->retain = true;
154	            break;
155	
156	          case 'w':
157	            cfg->wait_secs = atoi(optarg);
158	            break;
159	
160	          default:
161	            show_usage(argv[0]);
162	            return ERROR;
163	        }
164	    }
165	
166	  if (cfg->host == NULL || cfg->host[0] == '\0')
167	    {
168	      fprintf(stderr, "ERROR: broker host (-h) is required\n");
169	      show_usage(argv[0]);
170	      return ERROR;
171	    }
