182	/* 建立 TCP 连接（getaddrinfo 支持 IP 字面量；域名需启用 DNS 客户端） */
183	
184	static int tcp_connect(FAR const char *host, FAR const char *port)
185	{
186	  struct addrinfo hints;
187	  FAR struct addrinfo *res = NULL;
188	  FAR struct addrinfo *it;
189	  struct timeval tv;
190	  int fd = ERROR;
191	  int ret;
192	
193	  memset(&hints, 0, sizeof(hints));
194	  hints.ai_family   = AF_INET;
195	  hints.ai_socktype = SOCK_STREAM;
196	
197	  ret = getaddrinfo(host, port, &hints, &res);
198	  if (ret != 0)
199	    {
200	      fprintf(stderr, "ERROR: getaddrinfo(%s:%s): %s\n",
201	              host, port, gai_strerror(ret));
202	      return ERROR;
203	    }
204	
205	  for (it = res; it != NULL; it = it->ai_next)
206	    {
207	      fd = socket(it->ai_family, it->ai_socktype, it->ai_protocol);
208	      if (fd < 0)
209	        {
210	          continue;
211	        }
212	
213	      if (connect(fd, it->ai_addr, it->ai_addrlen) == 0)
214	        {
215	          break;
216	        }
217	
218	      close(fd);
219	      fd = ERROR;
220	    }
221	
222	  freeaddrinfo(res);
223	  if (fd < 0)
224	    {
225	      return ERROR;
226	    }
227	
228	  /* 接收/发送超时 2s：mqtt_sync 的 recv 是阻塞的，没有超时会在
229	   * CONNACK/PUBACK 不到时无限卡死（见 mqtt_pal_recvall）。 */
230	
231	  tv.tv_sec  = 5;
232	  tv.tv_usec = 0;
233	  setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
234	  setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
235	  return fd;
236	}
