238	/* 构造合同 §4.1 的 status JSON（snprintf 手拼，不引入 cjson） */
239	
240	static void build_status_payload(FAR char *buf, size_t bufsz)
241	{
242	  struct timespec mono;
243	  long long uptime_ms = 0;
244	
245	  if (clock_gettime(CLOCK_MONOTONIC, &mono) == 0)
246	    {
247	      uptime_ms = (long long)mono.tv_sec * 1000LL +
248	                  mono.tv_nsec / 1000000LL;
249	    }
250	
251	  vg_mqtt_format_status(buf, bufsz, vg_device_id(), "rj45", uptime_ms,
252	                        0);
253	}
