258	
259	int main(int argc, FAR char *argv[])
260	{
261	  struct vgmqtt_cfg_s cfg;
262	  struct mqtt_client client;
263	  static uint8_t sendbuf[VGMQTT_TXBUFSZ];
264	  static uint8_t recvbuf[VGMQTT_RXBUFSZ];
265	  char payload[256];
266	  char topic[VG_MQTT_TOPIC_MAX];
267	  char will[96];
268	  const char *devid;
269	  uint8_t pubflags;
270	  uint8_t connflags;
271	  long long start_ms;
272	  int fd;
273	  int ret;
274	
275	  if (parse_args(argc, argv, &cfg) != OK)
276	    {
277	      return ERROR;
278	    }
279	
280	  devid = vg_device_id();
281	  if (cfg.topic == NULL)
282	    {
283	      if (vg_mqtt_topic(topic, sizeof(topic), devid, "status") != 0)
284	        {
285	          fprintf(stderr, "ERROR: topic\n");
286	          return ERROR;
287	        }
288	
289	      cfg.topic = topic;
290	    }
291	
292	  if (vg_mqtt_format_lwt(will, sizeof(will), devid) != 0)
293	    {
294	      fprintf(stderr, "ERROR: lwt\n");
295	      return ERROR;
296	    }
297	
298	  if (cfg.msg == NULL)
299	    {
300	      build_status_payload(payload, sizeof(payload));
301	      cfg.msg = payload;
302	    }
303	
304	  printf("vgmqtt: connecting to %s:%s topic=%s qos=%u retain=%s wait=%us\n",
305	         cfg.host, cfg.port, cfg.topic, cfg.qos,
306	         cfg.retain ? "on" : "off", cfg.wait_secs);
307	
308	  fd = tcp_connect(cfg.host, cfg.port);
309	  if (fd < 0)
310	    {
311	      fprintf(stderr, "ERROR: cannot connect to %s:%s (%s)\n",
312	              cfg.host, cfg.port, strerror(errno));
313	      return ERROR;
314	    }
315	
316	  mqtt_init(&client, fd, sendbuf, sizeof(sendbuf),
317	            recvbuf, sizeof(recvbuf), NULL);
318	
319	  /* LWT：掉线时云侧收到同 topic 的 {"online":false}，retained */
320	
321	  connflags = MQTT_CONNECT_CLEAN_SESSION |
322	              MQTT_CONNECT_WILL_QOS_0 |
323	              MQTT_CONNECT_WILL_RETAIN;
324	
325	  /* keepalive 60s：与常驻会话一致 */
326	
327	  ret = mqtt_connect(&client, devid, cfg.topic,
328	                     will, strlen(will),
329	                     cfg.user, cfg.pass, connflags,
330	                     (uint16_t)CONFIG_VG_MQTT_KEEPALIVE);
331	  if (ret != MQTT_OK)
332	    {
333	      fprintf(stderr, "ERROR: mqtt_connect failed: %s\n",
334	              mqtt_error_str((enum MQTTErrors)ret));
335	      close(fd);
336	      return ERROR;
337	    }
338	
339	  /* 等待 CONNACK（event_connect 由 mqtt_sync 处理 CONNACK 时置位），
340	   * 最多 10s；mqtt_connect 返回 OK 只代表 CONNECT 已排队，不代表连上。 */
341	
342	  start_ms = now_ms();
343	  while (!client.event_connect && client.error == MQTT_OK &&
344	         now_ms() - start_ms < 10000)
345	    {
346	      mqtt_sync(&client);
347	      usleep(50000);
348	    }
349	
350	  if (!client.event_connect)
351	    {
352	      fprintf(stderr, "ERROR: no CONNACK from broker (err=%s)\n",
353	              mqtt_error_str(client.error));
354	      close(fd);
355	      return ERROR;
356	    }
357	
358	  printf("vgmqtt: connected (client_id=%s)\n", devid);
359	
360	  /* cfg.qos 存数字 0/1/2，MQTT-C 发布标志需要编码值（qos << 1） */
361	
362	  pubflags = (uint8_t)(cfg.qos << 1);
363	  if (cfg.retain)
364	    {
365	      pubflags |= MQTT_PUBLISH_RETAIN;
366	    }
367	
368	  ret = mqtt_publish(&client, cfg.topic, cfg.msg, strlen(cfg.msg),
369	                     pubflags);
370	  if (ret != MQTT_OK)
371	    {
372	      fprintf(stderr, "ERROR: mqtt_publish failed: %s\n",
373	              mqtt_error_str((enum MQTTErrors)ret));
374	      mqtt_disconnect(&client);
375	      close(fd);
376	      return ERROR;
377	    }
378	
379	  /* 确认 PUBLISH 已发出/已确认：MQTT-C 中消息完成后仍留在队列
380	   * （mqtt_mq_clean 只在发送缓冲不足时被调用），mqtt_mq_length 无法作为
381	   * 完成信号；改用 mqtt_mq_find(PUBLISH)——未完成时返回消息指针，
382	   * 完成后返回 NULL。 */
383	
384	  start_ms = now_ms();
385	  while (client.error == MQTT_OK &&
386	         mqtt_mq_find(&client.mq, MQTT_CONTROL_PUBLISH, NULL) != NULL &&
387	         now_ms() - start_ms < 10000)
388	    {
389	      mqtt_sync(&client);
390	      usleep(50000);
391	    }
392	
393	  if (client.error != MQTT_OK)
394	    {
395	      fprintf(stderr, "ERROR: publish failed: %s\n",
396	              mqtt_error_str(client.error));
397	      mqtt_disconnect(&client);
398	      close(fd);
399	      return ERROR;
400	    }
401	
402	  if (mqtt_mq_find(&client.mq, MQTT_CONTROL_PUBLISH, NULL) != NULL)
403	    {
404	      fprintf(stderr, "ERROR: publish not confirmed within 10s\n");
405	      mqtt_disconnect(&client);
406	      close(fd);
407	      return ERROR;
408	    }
409	
410	  printf("vgmqtt: published %zu bytes -> %s\n", strlen(cfg.msg),
411	         cfg.topic);
412	
413	  /* LWT 演示窗口：保持连接，等待期间拔线/断电可触发遗嘱 */
414	
415	  if (cfg.wait_secs > 0)
416	    {
417	      printf("vgmqtt: holding connection %us (pull cable/power to test LWT)...\n",
418	             cfg.wait_secs);
419	      sleep(cfg.wait_secs);
420	    }
421	
422	  mqtt_disconnect(&client);
423	  mqtt_sync(&client);   /* 正常退出发送 DISCONNECT，避免误触发 LWT */
424	  close(fd);
425	  return OK;
426	}
