1	/****************************************************************************
2	 * app/velaguard/host_tests/test_provision_creds.c
3	 *
4	 * The two guards that keep a lost LLM credential from looking like a broken
5	 * feature.  Both were added after the 2026-09-17 board came back with no
6	 * backend: the page said "AI 建议不可用" while the credentials were simply
7	 * absent, and the restore path had reported success onto a store that was not
8	 * checkable at the time.
9	 ****************************************************************************/
10	
11	#include <errno.h>
12	#include <stdio.h>
13	#include <string.h>
14	
15	#include "../vg_provision.h"
16	
17	/* vg_provision.c reaches for the sealer, the opener and the chip UID, none of
18	 * which exists off-target.  The predicates under test touch none of them, so
19	 * stub the three here rather than link the crypto translation unit - its
20	 * desktop branch carries an unused static that -Werror rejects.
21	 */
22	
23	int vg_provision_crypto_seal(const uint8_t uid[VG_PROVISION_UID_LEN],
24	                             const uint8_t *plain, size_t plain_len,
25	                             uint8_t *out, size_t outsz, size_t *out_len)
26	{
27	  (void)uid; (void)plain; (void)plain_len;
28	  (void)out; (void)outsz; (void)out_len;
29	  return -ENOSYS;
30	}
31	
32	int vg_provision_crypto_open(const uint8_t uid[VG_PROVISION_UID_LEN],
33	                             const uint8_t *blob, size_t blob_len,
34	                             uint8_t *plain, size_t plainsz,
35	                             size_t *plain_len)
36	{
37	  (void)uid; (void)blob; (void)blob_len;
38	  (void)plain; (void)plainsz; (void)plain_len;
39	  return -ENOSYS;
40	}
41	
42	int vg_device_id_read_uid(uint8_t uid[VG_PROVISION_UID_LEN]);
43	
44	int vg_device_id_read_uid(uint8_t uid[VG_PROVISION_UID_LEN])
45	{
46	  memset(uid, 0, VG_PROVISION_UID_LEN);
47	  return 0;
48	}
49	
50	static int expect_true(int cond, const char *msg)
51	{
52	  if (!cond)
53	    {
54	      fprintf(stderr, "FAIL: %s\n", msg);
55	      return 1;
56	    }
57	
58	  return 0;
59	}
60	
61	int main(void)
62	{
63	  int fails = 0;
64	
65	  /* The JSON the board actually writes when provisioning applied. */
66	
67	  fails += expect_true(
68	      vg_provision_creds_ready_in(
69	          "{\"llm_host\":\"token-plan-cn.xiaomimimo.com\","
70	          "\"llm_path\":\"/v1/chat/completions\","
71	          "\"llm_port\":\"443\",\"model\":\"mimo-v2.5\","
72	          "\"api_key\":\"tp-abc123\"}"),
73	      "a provisioned config reads ready");
74	
75	  /* The board state that produced the symptom: the file exists but carries no
76	   * LLM keys at all.  Reporting this as "ready" would keep the page blaming
77	   * the advice feature. */
78	
79	  fails += expect_true(
80	      !vg_provision_creds_ready_in("{\"feishu_app_id\":\"x\"}"),
81	      "a config without LLM keys is not ready");
82	
83	  /* Empty values, not absent ones.  This is what a masked write leaves behind,
84	   * and it is the subtler failure: the router gets a host and every call fails
85	   * instantly with no network traffic. */
86	
87	  fails += expect_true(
88	      !vg_provision_creds_ready_in("{\"llm_host\":\"\",\"api_key\":\"tp-x\"}"),
89	      "an empty host is not ready");
90	  fails += expect_true(
91	      !vg_provision_creds_ready_in(
92	          "{\"llm_host\":\"h.example\",\"api_key\":\"\"}"),
93	      "an empty key is not ready");
94	
95	  fails += expect_true(!vg_provision_creds_ready_in(""), "empty text is not ready");
96	  fails += expect_true(!vg_provision_creds_ready_in(NULL), "NULL is not ready");
97	  fails += expect_true(!vg_provision_creds_ready_in("{}"), "an empty object is not ready");
98	
99	  /* Storage guard.  A board whose /data fell back to RAM must be refused.
100	   * /dev/shm is tmpfs here and /proc is the pseudo filesystem, so both rejected
101	   * magics are reachable off-target.  Note /tmp is NOT usable as the positive
102	   * case: on this host it is itself tmpfs (magic 0x1021994), so the working
103	   * directory stands in for the eMMC mount.
104	   */
105	
106	  {
107	    struct
108	    {
109	      const char *path;
110	      int         want;
111	      const char *msg;
112	    } cases[] = {
113	      { ".",            0,       "a real directory is persistent" },
114	      { "/proc",         -ENODEV, "procfs is not a store" },
115	      { "/dev/shm",      -ENODEV, "tmpfs is not a store" },
116	      { "/no/such/dir",  -ENOENT, "a missing path reports itself" },
117	      { "",              -EINVAL, "an empty path is rejected" },
118	    };
119	    size_t i;
120	
121	    for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
122	      {
123	        int rc = vg_provision_store_is_persistent(cases[i].path);
124	
125	        if (cases[i].want == 0)
126	          {
127	            fails += expect_true(rc == 0, cases[i].msg);
128	          }
129	        else
130	          {
131	            fails += expect_true(rc == cases[i].want, cases[i].msg);
132	          }
133	      }
134	  }
135	
136	  /* The plain NULL guard, separate from the loop above because it is the one
137	   * caller error the sign of the return cannot express. */
138	
139	  fails += expect_true(vg_provision_store_is_persistent(NULL) == -EINVAL,
140	                       "NULL path is rejected");
141	
142	  if (fails == 0)
143	    {
144	      printf("test_provision_creds: OK\n");
145	    }
146	  else
147	    {
148	      printf("test_provision_creds: %d failure(s)\n", fails);
149	    }
150	
151	  return (fails == 0) ? 0 : 1;
152	}
153

