/* --- MQTT broker credentials ---------------------------------------------
 *
 * A second record in the same store, in its own sealed file.  It is separate
 * from the LLM record because the two have different lifetimes: the LLM
 * record is applied to /data/agent/config/config.json once per boot, while
 * the MQTT record is read every time the network manager opens a session.
 * Separate files also mean one cannot be written over the other.
 *
 * The plaintext of this record carries a "kind" tag that the LLM record does
 * not have, so a blob copied between the two files is rejected by both
 * readers instead of being accepted as the wrong credential.  Adding the tag
 * here rather than to the LLM record keeps already-provisioned boards
 * readable.
 */

#define VG_MQTT_CRED_FILE        "/data/velaguard/provision/mqtt_secrets.v1"
#define VG_MQTT_CRED_KIND        "mqtt"

/* Buffer sizes, terminator included.  The scanner in vg_provision.c needs one
 * spare byte past the last accepted character, so the longest accepted value
 * is one byte shorter than these.
 */
#define VG_MQTT_CRED_USER_MAX    64
#define VG_MQTT_CRED_PASS_MAX    128

struct vg_mqtt_credentials
{
  char username[VG_MQTT_CRED_USER_MAX];
  char password[VG_MQTT_CRED_PASS_MAX];
};

/* Parse decrypted MQTT credential JSON.  Rejects a record whose kind tag is
 * missing or wrong, and one with an empty or over-long field, so a record
 * meant for the other file cannot be used here. */

int vg_mqtt_cred_parse(const char *plain, struct vg_mqtt_credentials *out);

/* Validate a sealed blob and publish it as the MQTT credential.  The blob is
 * checked through the same path the session uses before the old record is
 * touched, so a truncated push cannot replace working credentials. */

int vg_mqtt_cred_install(const void *blob, size_t blob_len);

int vg_mqtt_cred_load(struct vg_mqtt_credentials *out);

bool vg_mqtt_cred_present(void);

/* One line describing the record without revealing it: presence, masked user,
 * password length, and the error when the record cannot be used. */

int vg_mqtt_cred_status(char *out, size_t outsz);

void vg_mqtt_cred_mask_user(const char *user, char *out, size_t outsz);
