/* SPDX-License-Identifier: Apache-2.0 */
/****************************************************************************
 * app/velaguard/host_tests/test_mqtt_cred.c
 *
 * Behaviour of the MQTT credential record.  The store is compiled in rather
 * than linked so the record paths can be pointed at this directory: the two
 * file names are the only thing that ties the board behaviour to /data.
 *
 * The crypto translation unit is replaced by a reversible stand-in, because
 * the desktop build of the real one is a stub and because these tests are
 * about the record's shape, its isolation from the LLM record, and the way a
 * failed write leaves the previous record alone.
 ****************************************************************************/

#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define VG_PROVISION_FILE "vgtest-llm_secrets.v1"
#define VG_MQTT_CRED_FILE "vgtest-mqtt_secrets.v1"

#include "../vg_provision.c"

/* --- stand-ins ----------------------------------------------------------- */

int vg_device_id_read_uid(uint8_t uid[VG_PROVISION_UID_LEN])
{
  memset(uid, 0x11, VG_PROVISION_UID_LEN);
  return 0;
}

/* Magic "TST", one length byte, then the plaintext XOR 0xa5. */

int vg_provision_crypto_seal(const uint8_t uid[VG_PROVISION_UID_LEN],
                             const uint8_t *plain, size_t plain_len,
                             uint8_t *out, size_t outsz, size_t *out_len)
{
  size_t i;

  (void)uid;

  if (plain == NULL || out == NULL || out_len == NULL || plain_len > 255 ||
      outsz < plain_len + 4)
    {
      return -EINVAL;
    }

  out[0] = 'T';
  out[1] = 'S';
  out[2] = 'T';
  out[3] = (uint8_t)plain_len;
  for (i = 0; i < plain_len; i++)
    {
      out[4 + i] = (uint8_t)(plain[i] ^ 0xa5);
    }

  *out_len = plain_len + 4;
  return 0;
}

int vg_provision_crypto_open(const uint8_t uid[VG_PROVISION_UID_LEN],
                             const uint8_t *blob, size_t blob_len,
                             uint8_t *plain, size_t plainsz,
                             size_t *plain_len)
{
  size_t n;
  size_t i;

  (void)uid;

  if (blob == NULL || plain == NULL || plain_len == NULL || blob_len < 4 ||
      blob[0] != 'T' || blob[1] != 'S' || blob[2] != 'T')
    {
      return -EACCES;
    }

  n = blob[3];
  if (blob_len != n + 4 || plainsz <= n)
    {
      return -EINVAL;
    }

  for (i = 0; i < n; i++)
    {
      plain[i] = (uint8_t)(blob[4 + i] ^ 0xa5);
    }

  plain[n] = '\0';
  *plain_len = n;
  return 0;
}

/* --- helpers ------------------------------------------------------------- */

static int fails;

static void expect(int cond, const char *msg)
{
  if (!cond)
    {
      fprintf(stderr, "FAIL: %s\n", msg);
      fails++;
    }
}

