static int put_record(const char *path, const char *json)
{
  uint8_t blob[1024];
  size_t blob_len = 0;
  FILE *fp;

  if (vg_provision_crypto_seal(NULL, (const uint8_t *)json, strlen(json),
                               blob, sizeof(blob), &blob_len) != 0)
    {
      return -1;
    }

  fp = fopen(path, "wb");
  if (fp == NULL)
