184	/* MQTT record.  Unlike the LLM one there is no boot step: the network manager
185	 * reads the record every time it opens a session, so a committed record takes
186	 * effect at the next connect without a restart. */
187	
188	static int cmd_mqtt_commit(void)
189	{
190	  struct stat st;
191	  uint8_t blob[VG_PROVISION_BLOB_MAX];
192	  ssize_t n;
193	  int fd;
194	  int ret;
195	
196	  if (stat(VG_MQTT_STAGING_FILE, &st) != 0 || st.st_size <= 0)
197	    {
198	      printf("vgprovision: nothing staged for mqtt\n");
199	      return -EINVAL;
200	    }
201	
202	  if (st.st_size > (off_t)sizeof(blob))
203	    {
204	      printf("vgprovision: staged mqtt record too large (%ld bytes)\n",
205	             (long)st.st_size);
206	      return -E2BIG;
207	    }
208	
209	  fd = open(VG_MQTT_STAGING_FILE, O_RDONLY);
210	  if (fd < 0)
211	    {
212	      return -errno;
213	    }
214	
215	  n = read(fd, blob, sizeof(blob));
216	  close(fd);
217	  if (n <= 0)
218	    {
219	      return (n == 0) ? -EINVAL : -EIO;
220	    }
221	
222	  /* The staged bytes are decrypted and parsed before the working record is
223	   * touched, so a push that was cut short, or one carrying the LLM blob,
224	   * leaves the board with the credentials it already had. */
225	
226	  ret = vg_mqtt_cred_install(blob, (size_t)n);
227	  memset(blob, 0, sizeof(blob));
228	
229	  /* The staged bytes are spent either way: a refused push must not be left
230	   * behind for the next one to append to, which would produce a record that
231	   * is neither push.  The normal sequence is put... put, commit, with no
232	   * wipe in between, so a refused commit leaves the operator with an empty
233	   * staging file to push into again. */
234	
235	  (void)unlink(VG_MQTT_STAGING_FILE);
236	  if (ret < 0)
237	    {
238	      printf("vgprovision: mqtt commit refused (%d); previous record kept\n",
239	             ret);
240	      return ret;
241	    }
242	
243	  printf("vgprovision: mqtt credentials committed to %s (%ld bytes)\n",
244	         VG_MQTT_CRED_FILE, (long)n);
245	  warn_if_not_persistent();
246	  return 0;
247	}
